import {describe, it, expect} from 'vitest';
import {aggregateUsage} from './orchestratorHelpers.js';
import type {UsageMetadata, TurnUsage} from '../types/ai.js';

describe('aggregateUsage', () => {
  it('sums two usage objects', () => {
    const u1: UsageMetadata = {inputTokens: 1, outputTokens: 2, totalTokens: 3};
    const u2: UsageMetadata = {inputTokens: 10, outputTokens: 20, totalTokens: 30};
    const total: TurnUsage | undefined = aggregateUsage(u1, u2);
    expect(total).toEqual({inputTokens: 11, outputTokens: 22, totalTokens: 33});
  });

  it('returns current if total is undefined', () => {
    const current: UsageMetadata = {inputTokens: 1, outputTokens: 2, totalTokens: 3};
    expect(aggregateUsage(undefined, current)).toEqual(current);
  });

  it('returns total if current is undefined', () => {
    const total: TurnUsage = {inputTokens: 1, outputTokens: 2, totalTokens: 3};
    expect(aggregateUsage(total, undefined)).toEqual(total);
  });

  it('returns undefined if both are undefined', () => {
    expect(aggregateUsage(undefined, undefined)).toBeUndefined();
  });
});
